      state.constructionInvoices.push(inv);
      if(pfCloud() && window.ESPFCLOUD){ window.ESPFCLOUD.ensureUuid(inv); pfCloudWrite("construction_invoices", window.ESPFCLOUD.invoiceToDb(inv)); }
