  function lsGeoPop(regId, provId, cityId) {
    const reg = document.getElementById(regId), prov = document.getElementById(provId), city = document.getElementById(cityId);
    if (!reg || !prov || !city) return;
    const provinces = lsGeoProvinces(reg.value);
    const keepProv = provinces.indexOf(prov.value) >= 0;
    const newProv = keepProv ? prov.value : (provinces[0] || "");
    prov.innerHTML = lsGeoOpts(provinces, newProv);
    const cities = lsGeoCities(reg.value, newProv);
    const keepCity = keepProv && cities.indexOf(city.value) >= 0;
    city.innerHTML = lsGeoOpts(cities, keepCity ? city.value : (cities[0] || ""));
  }
  function lsTxt(id, v, ph) { return '<input class="input" id="' + id + '" type="text" value="' + esc(v == null ? "" : v) + '"' + (ph ? ' placeholder="' + esc(ph) + '"' : "") + ">"; }
  function lsNum(id, v) { return '<input class="input input-num" id="' + id + '" type="text" inputmode="decimal" value="' + (C.num(v, 0) > 0 ? C.fmtNum(v) : "") + '" placeholder="0">'; }
  function lsPhotoThumb(url) {
    return '<div class="ls-photo-thumb" data-photo-url="' + esc(url) + '"><img ' + thumbAttrs(url) + ' alt="Photo" loading="lazy"><button type="button" class="ls-photo-remove" data-ls-photo-remove title="Remove photo">&times;</button></div>';
  }
  function lsReadAsDataUrl(file) {
    return new Promise(function (resolve, reject) {
      const rd = new FileReader();
      rd.onload = () => resolve(rd.result);
      rd.onerror = () => reject(rd.error || new Error("Could not read image"));
      rd.readAsDataURL(file);
    });
  }
  // A small JPEG copy (640 px on the long side) for lists and cards; null if
  // the browser can't read the image.
  function lsMakeThumb(file) {
    return new Promise(function (resolve) {
      if (!/image\/(jpeg|png|webp|gif|bmp|avif)/.test(file.type || "")) { resolve(null); return; }
      lsReadAsDataUrl(file).then(function (dataUrl) {
        const img = new Image();
        img.onload = function () {
          const ratio = Math.min(1, 640 / Math.max(img.width, img.height));
          const canvas = document.createElement("canvas");
          canvas.width = Math.max(1, Math.round(img.width * ratio)); canvas.height = Math.max(1, Math.round(img.height * ratio));
          const ctx = canvas.getContext("2d");
          try { ctx.imageSmoothingQuality = "high"; ctx.drawImage(img, 0, 0, canvas.width, canvas.height); } catch (e) { resolve(null); return; }
          canvas.toBlob(blob => resolve(blob || null), "image/jpeg", 0.72);
        };
        img.onerror = () => resolve(null);
        img.src = dataUrl;
      }).catch(() => resolve(null));
    });
  }
  // Downscale photos before upload: the site renders cards/detail at <= 1280px,
  // and full-size originals burn storage and egress for no visible benefit.
  function lsOptimizeImage(file) {
    return new Promise(function (resolve) {
      const keep = () => resolve({ blob: file, contentType: file.type, ext: (file.name.match(/\.([a-zA-Z0-9]+)$/) || [, "jpg"])[1].toLowerCase() });
      if (!/image\/(jpeg|png|webp|gif|bmp|avif)/.test(file.type || "")) { keep(); return; }
      lsReadAsDataUrl(file).then(function (dataUrl) {
        const img = new Image();
        img.onload = function () {
          const MAX_SIDE = 1280;
          const ratio = Math.min(1, MAX_SIDE / Math.max(img.width, img.height));
          const w = Math.max(1, Math.round(img.width * ratio));
          const h = Math.max(1, Math.round(img.height * ratio));
          const canvas = document.createElement("canvas");
          canvas.width = w; canvas.height = h;
          const ctx = canvas.getContext("2d");
          try { ctx.imageSmoothingQuality = "high"; } catch (e) {}
          try { ctx.drawImage(img, 0, 0, w, h); } catch (e) { keep(); return; }
          canvas.toBlob(function (blob) {
            if (blob && blob.size < file.size) resolve({ blob: blob, contentType: "image/jpeg", ext: "jpg" });
            else keep();
          }, "image/jpeg", 0.8);
        };
        img.onerror = keep;
        img.src = dataUrl;
      }).catch(keep);
    });
  }
  async function lsUploadPhotos(files) {
    const list = Array.from(files || []).filter(f => /^image\//.test(f.type || ""));
    if (!list.length) { toast("Choose a JPG, PNG or WebP image", "err"); return; }
    /* Cameras produce multi-MB originals, so the checks run against what will
       actually be stored: the photo is optimized first (<=1280px JPEG), then
       held to the 2 MB cap. The old 2 MB pre-check rejected a 3 MB photo that
       compresses to 300 KB, which forced manual conversion for no reason; the
       high pre-limit now only guards against decoding absurd files. */
    const RAW_LIMIT = 15 * 1024 * 1024;
    const OUT_LIMIT = 2 * 1024 * 1024;
    // Local fallback (no cloud session): attach images as data URLs so demo/offline drafts keep photos.
    if (!SB || !SB.storage || !currentUser || !currentUser.id) {
      const status = $("#ls-photo-status");
      let done = 0;
      for (const file of list) {
        if (file.size > RAW_LIMIT) { toast(esc(file.name) + " is too large (max 15 MB)", "err"); done += 1; continue; }
        let optimized;
        try { optimized = await lsOptimizeImage(file); } catch (e) { toast("Could not process " + esc(file.name), "err"); done += 1; continue; }
        if (optimized.blob.size > OUT_LIMIT) { toast(esc(file.name) + " is larger than 2 MB", "err"); done += 1; continue; }
        const rd = new FileReader();
        rd.onload = () => {
          const ta = $("#ls-photos");
          if (ta) {
            const lines = ta.value.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
            lines.push(rd.result);
            ta.value = lines.join("\n");
          }
          const previews = $("#ls-photo-previews");
          if (previews) previews.insertAdjacentHTML("beforeend", lsPhotoThumb(rd.result));
          done += 1;
          if (status) status.textContent = done < list.length ? ("Attached " + done + "/" + list.length + "…") : "Photos attached locally";
        };
        rd.readAsDataURL(optimized.blob);
        if (done >= 12) break; // sanity cap per batch
      }
      return;
    }
    const status = $("#ls-photo-status");
    if (status) status.textContent = "Uploading " + list.length + " photo" + (list.length === 1 ? "" : "s") + "…";
    let done = 0;
    for (const file of list) {
      if (file.size > RAW_LIMIT) { toast(esc(file.name) + " is too large (max 15 MB)", "err"); done += 1; continue; }
      let optimized;
      try { optimized = await lsOptimizeImage(file); } catch (e) { toast("Could not process " + esc(file.name), "err"); done += 1; continue; }
      if (optimized.blob.size > OUT_LIMIT) { toast(esc(file.name) + " is larger than 2 MB", "err"); done += 1; continue; }
      const base = currentUser.id + "/" + (crypto.randomUUID ? crypto.randomUUID() : Date.now() + "-" + Math.floor(Math.random() * 1e9));
      const small = await lsMakeThumb(file);
      // "-full" in the name says a small copy sits next to it (js/util.js thumbUrl).
      const path = base + (small ? "-full." : ".") + optimized.ext;
      try {
        const retrying = () => { if (status) status.textContent = "Signal dropped, trying " + file.name + " again…"; };
        const { error } = await storageUpload("listing-photos", path, optimized.blob, { contentType: optimized.contentType, upsert: false, cacheControl: "31536000" }, retrying);
        if (error) throw error;
        // If the small copy doesn't make it, lists fall back to the full photo.
        if (small) await storageUpload("listing-photos", base + "-thumb.jpg", small, { contentType: "image/jpeg", upsert: false, cacheControl: "31536000" }, retrying);
        const { data } = SB.storage.from("listing-photos").getPublicUrl(path);
        const url = data && data.publicUrl ? data.publicUrl : "";
        if (!url) throw new Error("Could not build the photo URL");
        const ta = $("#ls-photos");
        if (ta) {
          const lines = ta.value.split(/\r?\n/).map(s => s.trim()).filter(Boolean);
          lines.push(url);
          ta.value = lines.join("\n");
        }
        const previews = $("#ls-photo-previews");
        if (previews) previews.insertAdjacentHTML("beforeend", lsPhotoThumb(url));
        toast("Uploaded " + esc(file.name));
      } catch (e) {
        toast("Upload failed: " + esc(friendlyErr(e.message || "Unknown error")), "err");
      } finally {
        done += 1;
        if (status) status.textContent = done < list.length ? "Uploading " + (done + 1) + "/" + list.length + "…" : "";
      }
    }
  }
