  function randomTempPassword(len) {
    const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789";
    let out = "";
    for (let i = 0; i < (len || 12); i++) out += chars[Math.floor(Math.random() * chars.length)];
    return out;
  }
