  /* ================= PHONE ALERTS (web push) =================
   * A person turns alerts on in Settings; the phone's subscription is stored
   * with push_subscribe() (supabase/migrations/0003) and the GitHub workflow
   * push-alerts.yml passes new notifications on to it. The public key is in
   * push_config, made by a super-admin here; the private key is only a GitHub
   * secret (VAPID_PRIVATE_KEY). */
  const U = window.ESREALTY_UTIL || {};
  const pushState = { supported: false, key: "", subscribed: false };
  function pushSupported() { return "serviceWorker" in navigator && "PushManager" in window && "Notification" in window && !!U.b64urlBytes; }
  function pushCloud() { return !!(SB && currentUser && currentUser.id && !currentUser.demo); }
  async function refreshPushState() {
    pushState.supported = pushSupported();
    if (pushCloud()) {
      try { const r = await SB.from("push_config").select("public_key").eq("id", 1).maybeSingle(); pushState.key = (r && r.data && r.data.public_key) || ""; } catch (e) { pushState.key = ""; }
    } else pushState.key = "";
    pushState.subscribed = false;
    if (pushState.supported) {
      try { const reg = await navigator.serviceWorker.getRegistration(); const sub = reg && reg.pushManager ? await reg.pushManager.getSubscription() : null; pushState.subscribed = !!sub; } catch (e) {}
    }
  }
  function pushCardHtml(extra) {
    const ios = /iPhone|iPad|iPod/.test(navigator.userAgent || "");
    const installed = !!(window.matchMedia && window.matchMedia("(display-mode: standalone)").matches);
    let status, action = "";
    if (!pushCloud()) status = "Phone alerts work with a live account, not in the demo.";
    else if (!pushState.supported) status = ios && !installed ? "On iPhone: tap Share, then Add to Home Screen. Open SEA ESTATES from the home screen and turn alerts on here." : "This browser can't show phone alerts. Use Chrome on Android, or the app added to your home screen.";
    else if (!pushState.key) status = roleIs("super-admin") ? "Not set up yet: make the keys below first." : "Not set up yet. Ask a super-admin to set up phone alerts.";
    else if (pushState.subscribed) { status = "On for this phone: new leads, leads assigned to you, rent reminders and tenant requests show up even when the app is closed."; action = '<button class="btn btn-ghost" data-push-off>' + icon("x", 14) + " Turn off on this phone</button>"; }
    else { status = "Get new leads, leads assigned to you, rent reminders and tenant requests on this phone, even when the app is closed."; action = '<button class="btn btn-primary" data-push-on>' + icon("bell", 15) + " Turn on phone alerts</button>"; }
    let h = '<div class="card card-pad mt-16" id="st-push"><h3>' + icon("bell", 15) + ' Phone alerts</h3><p class="dim mt-4">' + esc(status) + "</p>" +
      (action ? '<div class="row mt-12" style="gap:8px;flex-wrap:wrap">' + action + "</div>" : "");
    if (roleIs("super-admin") && pushCloud()) {
      h += '<details class="mt-16"' + (pushState.key && !extra ? "" : " open") + '><summary><b>Set up (super-admin)</b></summary>' +
        '<p class="dim mt-8">' + (pushState.key ? "Keys are set. Making new keys turns alerts off on every phone until each person turns them on again." : "Make the alert keys once, here in your browser. The private key is shown once for you to store in GitHub; it isn't saved anywhere else.") + "</p>" +
        '<div class="row mt-8"><button class="btn btn-ghost" data-push-keys>' + icon("key", 14) + (pushState.key ? " Make new keys" : " Make keys") + "</button></div>" +
        '<div id="st-push-keys">' + (extra || "") + "</div></details>";
    }
    return h + "</div>";
  }
  function redrawPushCard(extra) {
    const card = document.getElementById("st-push");
    if (card) card.outerHTML = pushCardHtml(extra);
  }
  async function pushAction(btn, fn, okMsg) {
    if (btn.disabled) return;
    btn.disabled = true;
    try { await fn(); toast(okMsg); }
    catch (e) { toast(friendlyErr(String((e && e.message) || e)), "err"); }
    redrawPushCard();
  }
  async function pushTurnOn() {
    if (!pushState.key) throw new Error("Phone alerts aren't set up yet.");
    const perm = await Notification.requestPermission();
    if (perm !== "granted") throw new Error("Notifications are blocked for this site. Allow them in the browser's site settings, then try again.");
    const reg = await navigator.serviceWorker.ready;
    const old = await reg.pushManager.getSubscription();
    if (old) { try { await old.unsubscribe(); } catch (e) {} } // one made with an old key won't work
    const sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: U.b64urlBytes(pushState.key) });
    const j = sub.toJSON();
    const res = await SB.rpc("push_subscribe", { p_endpoint: j.endpoint, p_p256dh: j.keys.p256dh, p_auth: j.keys.auth, p_ua: String(navigator.userAgent || "").slice(0, 200) });
    if (res.error) { try { await sub.unsubscribe(); } catch (e) {} throw res.error; }
    pushState.subscribed = true;
  }
  async function pushTurnOff() {
    const reg = await navigator.serviceWorker.getRegistration();
    const sub = reg && reg.pushManager ? await reg.pushManager.getSubscription() : null;
    if (sub) {
      try { await SB.from("push_subscriptions").delete().eq("endpoint", sub.endpoint); } catch (e) {}
      try { await sub.unsubscribe(); } catch (e) {}
    }
    pushState.subscribed = false;
  }
  async function pushMakeKeys(btn) {
    if (btn.disabled) return;
    if (pushState.key && !window.confirm("Make new keys? Phone alerts stop on every phone until each person turns them on again.")) return;
    btn.disabled = true;
    try {
      const k = await U.makePushKeys();
      const res = await SB.rpc("push_set_public_key", { p_key: k.publicKey });
      if (res.error) throw res.error;
      pushState.key = k.publicKey; pushState.subscribed = false;
      redrawPushCard('<div class="pms-sent-note mt-12"><b>Keys made. Two steps in GitHub (repository tradersgag6/esrealty):</b>' +
        '<ol class="mt-8"><li>Settings &gt; Secrets and variables &gt; Actions &gt; <b>New repository secret</b>. Name: <code>VAPID_PRIVATE_KEY</code>. Secret: the private key below.</li>' +
        '<li>Same page, <b>Variables</b> tab &gt; <b>New repository variable</b>. Name: <code>PUSH_ALERTS</code>. Value: <code>on</code>.</li>' +
        '<li>Then turn on phone alerts above, on each phone.</li></ol>' +
        '<label for="st-push-private">Private key (shown once; keep it secret)</label><div class="row mt-8" style="gap:8px"><input class="input grow" id="st-push-private" readonly value="' + esc(k.privateKey) + '"><button type="button" class="btn btn-ghost" data-push-copy>' + icon("copy", 14) + " Copy</button></div></div>");
      toast("Phone alert keys made");
    } catch (e) {
      btn.disabled = false;
      toast(friendlyErr(String((e && e.message) || e)), "err");
    }
  }
  function settingsChangePassword() {
    const $v = id => { const el = document.getElementById(id); return el ? el.value : ""; };
    const cur = $v("st-pass-cur"), nw = $v("st-pass-new"), cf = $v("st-pass-conf");
    if (!cur) { toast("Enter your current password", "err"); return; }
    if (!nw || nw.length < 6) { toast("New password must be at least 6 characters", "err"); return; }
    if (nw !== cf) { toast("New passwords do not match", "err"); return; }
    const cloud = !!(SB && currentUser && currentUser.id && !currentUser.demo);
    const clearFields = () => ["st-pass-cur", "st-pass-new", "st-pass-conf"].forEach(i => { const el = document.getElementById(i); if (el) el.value = ""; });
    if (cloud) {
      const update = async () => {
        const v = await SB.auth.signInWithPassword({ email: currentUser.email, password: cur });
        if (v.error) {
          const low = String(v.error.message || "").toLowerCase();
          if (/invalid login credentials/.test(low)) { toast("Current password is incorrect", "err"); return; }
          toast("Could not verify current password: " + esc(v.error.message), "err");
          return;
        }
        const res = await SB.auth.updateUser({ password: nw, data: { must_change_password: false } });
        if (res.error) {
          const low = String(res.error.message || "").toLowerCase();
          if (/different|same as/.test(low)) { toast("New password must be different from your current one", "err"); return; }
          toast("Could not change password: " + esc(res.error.message), "err");
          return;
        }
        clearFields();
        currentUser.mustChangePassword = false;
        render();
        toast("Password updated successfully");
      };
      update();
      return;
    }
    const em = String(currentUser.email || "").toLowerCase();
    let users = [];
    try { users = JSON.parse(localStorage.getItem("esrealty_users") || "[]"); } catch (e) {}
    const rec = users.find(u => String(u.email || "").toLowerCase() === em);
    if (rec && rec.password && rec.password !== cur) { toast("Current password is incorrect", "err"); return; }
    if (rec) rec.password = nw; else users.push({ email: em, role: userRole(), createdAt: Date.now(), password: nw });
    localStorage.setItem("esrealty_users", JSON.stringify(users));
    clearFields();
    toast("Password updated successfully");
  }
  // Licence numbers are checked when an account is approved; after that only a
  // super-admin can change them (phase1_security_rest.sql enforces this too).
  function settingsLicenceLocked() {
    return !!(SB && currentUser && currentUser.id && !currentUser.demo && currentUser.registrationStatus === "approved" && userRole() !== "super-admin");
  }
  // An approved broker's or agent's name is locked too (migration 0014): agent pages show it.
  function settingsNameLocked() {
    return settingsLicenceLocked() && (userRole() === "broker" || userRole() === "agent");
  }
  function settingsSaveForm() {
    const $v = id => { const el = document.getElementById(id); return el ? el.value.trim() : ""; };
    const name = $v("st-name"), email = $v("st-email");
    if (!name) { toast("Full name is required", "err"); return; }
    if (!email) { toast("Email is required", "err"); return; }
    const data = { name: name, email: email, phone: $v("st-phone"), agency: $v("st-agency"), prc: $v("st-prc"), resa: $v("st-resa") };
    const cloud = !!(SB && currentUser && currentUser.id && !currentUser.demo);
    const doFinish = (msg) => { toast(msg || "Profile saved"); render(); };
    if (cloud) {
      const updateProfile = async () => {
        const payload = { full_name: data.name, agency: data.agency, prc: data.prc, resa: data.resa, phone: data.phone };
        if (settingsLicenceLocked()) { delete payload.prc; delete payload.resa; data.prc = currentUser.prc || ""; data.resa = currentUser.resa || ""; }
        if (settingsNameLocked()) { delete payload.full_name; data.name = currentUser.name || data.name; }
        const res = await SB.from("profiles").update(payload).eq("id", currentUser.id);
        if (res.error) {
          const low = String(res.error.message || "").toLowerCase();
          if (low.indexOf("permission denied for column") >= 0 || low.indexOf("column") >= 0 && low.indexOf("does not exist") >= 0) {
            const r1 = await SB.from("profiles").update({ full_name: data.name }).eq("id", currentUser.id);
            if (r1.error) { toast("Could not save profile: " + esc(r1.error.message), "err"); return; }
            currentUser.name = data.name;
            currentUser.phone = data.phone;
            save();
            toastHtml("Profile saved. PRC/RESA/agency/phone need column grants — run <b>patch_profile_self_edit.sql</b> in the Supabase SQL Editor once.");
            render();
            return;
          }
          toast("Could not save profile: " + esc(res.error.message || "Unknown error"), "err");
          return;
        }
        currentUser.name = data.name;
        currentUser.agency = data.agency; currentUser.prc = data.prc; currentUser.resa = data.resa; currentUser.phone = data.phone;
        save();
        doFinish("Profile saved to Supabase");
      };
      updateProfile();
      return;
    }
    currentUser.name = data.name;
    currentUser.email = data.email;
    currentUser.phone = data.phone; currentUser.agency = data.agency; currentUser.prc = data.prc; currentUser.resa = data.resa;
    let users = [];
    try { users = JSON.parse(localStorage.getItem("esrealty_users") || "[]"); } catch (e) {}
    const em = String(data.email || "").toLowerCase();
    const rec = users.find(u => String(u.email || "").toLowerCase() === em);
    if (rec) { rec.name = data.name; rec.phone = data.phone; rec.agency = data.agency; rec.prc = data.prc; rec.resa = data.resa; }
    else users.push(Object.assign({ email: em, role: userRole(), createdAt: Date.now() }, data));
    localStorage.setItem("esrealty_users", JSON.stringify(users));
    if (state.users) {
      const su = (state.users || []).find(u => String(u.email || "").toLowerCase() === em);
      if (su) Object.assign(su, { name: data.name, phone: data.phone, agency: data.agency, prc: data.prc, resa: data.resa });
    }
    saveUser(currentUser);
    save();
    doFinish("Profile saved");
  }
  function backupIsSecretKey(k) { return /pass(word)?|passwd|pwd|^pw$|^pass$|secret|api[_-]?key|token|pin$/i.test(String(k)); }
  function backupStripObject(node) {
    if (!node || typeof node !== "object") return;
    if (Array.isArray(node)) { node.forEach(backupStripObject); return; }
    Object.keys(node).forEach(k => {
      if (backupIsSecretKey(k)) node[k] = undefined;
      else if (node[k] && typeof node[k] === "object") backupStripObject(node[k]);
    });
  }
  function backupLocalUsers() {
    let users = [];
    try { users = JSON.parse(localStorage.getItem("esrealty_users") || "[]"); } catch (e) {}
    return users.map(u => Object.keys(u).reduce((o, k) => { if (!backupIsSecretKey(k)) o[k] = u[k]; return o; }, {}));
  }
  async function backupCloud() {
    const result = { listings: [], leads: [], profiles: [], storage: { photoUrls: [], documentPaths: [], files: [] } };
    if (SB && currentUser && currentUser.id) {
      try { const { data } = await selectAllPages(() => SB.from("crm_leads").select("id,ref,name,assigned_to,assigned_to_id,payload,created_by,updated_at").order("updated_at", { ascending: false }).order("id", { ascending: true })); if (Array.isArray(data)) result.leads = data; } catch (e) {}
      try { const res = await SB.rpc("admin_list_profiles"); if (Array.isArray(res.data)) result.profiles = res.data; } catch (e) {}
      const seenU = {}, seenP = {};
      (state.listings || []).forEach(l => (l.images || []).forEach(i => { const u = i.url; if (u && /supabase\.co\/storage/.test(u) && !seenU[u]) { seenU[u] = 1; result.storage.photoUrls.push(u); } }));
      (state.docVault || []).concat((state.transactions || []).reduce((a, t) => a.concat(t.documents || []), [])).forEach(d => { if (d.storagePath && !seenP[d.storagePath]) { seenP[d.storagePath] = 1; result.storage.documentPaths.push(d.storagePath); } });
      const seenF = {};
      const raw = [];
      try { const { data } = await SB.storage.from("listing-photos").list("", { limit: 5000 }); raw.push(["listing-photos", data]); } catch (e) {}
      try { const { data } = await SB.storage.from("private-documents").list("", { limit: 5000 }); raw.push(["private-documents", data]); } catch (e) {}
      raw.forEach(([bucket, data]) => (Array.isArray(data) ? data : []).forEach(f => {
        if (!f || typeof f !== "object" || (f.id !== undefined && f.metadata === undefined) || f.name === undefined) return;
        const name = String(f.name || "");
        if (!name || String(f.metadata && f.metadata.mimetype || "") === "application/octet-stream") return;
        const rec = { bucket: bucket, name: name, path: (f.pathname && String(f.pathname)) || name, size: Number(f.metadata && f.metadata.size || 0).toString(), mime: String(f.metadata && f.metadata.mimetype || ""), updatedAt: String(f.updated_at || f.updatedAt || "") };
        const key = bucket + "/" + name;
        if (!seenF[key]) { seenF[key] = 1; seenU[bucket + "/" + name] ? rec.inUse = true : 0; result.storage.files.push(rec); }
      }));
    }
    if (LISTINGS_API) {
      try {
        // page in safe chunks (the public API rejects per_page > 50).
        const fromCloud = await loadAllListingPages(LISTINGS_API.list, { sort: "date_desc" });
        fromCloud.forEach(l => { if (l && l.id && !result.listings.find(x => x.id === l.id)) result.listings.push(l); });
      } catch (e) {}
      if (currentUser && currentUser.id) {
        try {
          const mine = await loadAllListingPages(LISTINGS_API.mine, {});
          mine.forEach(l => { if (l && l.id && !result.listings.find(x => x.id === l.id)) result.listings.push(l); });
        } catch (e) {}
      }
    }
    return result;
  }
  function backupDownload(filename, content, mime) {
    const blob = new Blob([content], { type: mime || "application/octet-stream" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = filename; a.style.display = "none";
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 4000);
  }
  async function settingsBackupJson(btn) {
    if (btn) { btn.dataset.label = btn.innerHTML; btn.disabled = true; btn.textContent = "Preparing backup…"; }
    try {
      const exportedAt = new Date().toISOString();
      const workspace = JSON.parse(JSON.stringify(state || {}));
      backupStripObject(workspace);
      const payload = {
        meta: { app: "SEA ESTATES", exportedAt: exportedAt, exportedBy: currentUser ? (currentUser.email || currentUser.name || "") : "", role: userRole(), source: "Super Admin backup" },
        workspace: workspace,
        localUsers: backupLocalUsers(),
        cloud: await backupCloud()
      };
      backupDownload("esrealty-backup-" + exportedAt.slice(0, 10) + ".json", JSON.stringify(payload, null, 1), "application/json");
      toast("Backup downloaded — store it in a secure, offline place");
    } catch (e) { toast("Backup failed: " + esc(friendlyErr(e.message || e)), "err"); }
    finally { if (btn) { btn.disabled = false; btn.innerHTML = btn.dataset.label || "Download full backup (.json)"; } }
  }
  function backupCsvRow(arr) {
    return arr.map(v => { const s = String(v == null ? "" : v).replace(/"/g, '""'); return /[",\n]/.test(s) ? '"' + s + '"' : s; }).join(",");
  }
  function settingsRestoreFromFile(inputEl) {
    const file = inputEl && inputEl.files && inputEl.files[0];
    if (!file) return;
    if (String(file.size || 0) > 20000000) { toast("Backup file too large (max 20 MB)", "err"); if (inputEl) inputEl.value = ""; return; }
    const btn = $("[data-restore-json]");
    const prevLabel = btn ? btn.innerHTML : "";
    if (btn) { btn.disabled = true; btn.textContent = "Reading backup…"; }
    const reader = new FileReader();
    reader.onerror = () => { toast("Could not read the backup file", "err"); if (btn) { btn.disabled = false; btn.innerHTML = prevLabel; } if (inputEl) inputEl.value = ""; };
    reader.onload = () => {
      try {
        const parsed = JSON.parse(String(reader.result || ""));
        if (!parsed || typeof parsed !== "object" || !parsed.workspace || typeof parsed.workspace !== "object" || Array.isArray(parsed.workspace)) {
          throw new Error("Not a SEA ESTATES backup file (missing workspace object)");
        }
        const ws = parsed.workspace;
        if (!Array.isArray(ws.deals) && (ws.deals === undefined || ws.deals === null)) {
          ws.deals = ws.deals || [];
        }
        const doRestore = async () => {
          const confirmed = await confirmModal({
            title: "Restore workspace backup?",
            message: "This will replace your current workspace (deals, portfolio, listings, leads, settings) with the contents of this backup, then save. This cannot be undone. Back up your current workspace first if unsure.",
            confirmLabel: "Restore workspace",
            danger: true,
            typeToConfirm: "RESTORE"
          });
          if (!confirmed) { toast("Restore cancelled"); if (btn) { btn.disabled = false; btn.innerHTML = prevLabel; } if (inputEl) inputEl.value = ""; return; }
          ws.current = ws.current || null;
          ws.view = ws.view || "dashboard";
          state = Object.assign(state || {}, ws);
          state.view = firstAllowedView();
          save();
          render({ keepScroll: false });
          toast("Workspace restored from backup", "ok");
          if (btn) { btn.disabled = false; btn.innerHTML = prevLabel; }
          if (inputEl) inputEl.value = "";
        };
        doRestore();
      } catch (e) {
        toast("Restore failed: " + esc(friendlyErr(e.message || e)), "err");
        if (btn) { btn.disabled = false; btn.innerHTML = prevLabel; }
        if (inputEl) inputEl.value = "";
      }
    };
    reader.readAsText(file);
  }
  async function settingsBackupCsv(kind, btn) {
    if (btn) { btn.dataset.label = btn.innerHTML; btn.disabled = true; btn.textContent = "Preparing…"; }
    try {
      const exportedAt = new Date().toISOString();
      const rows = [];
      if (kind === "leads") {
        try { await loadCloudLeads(); } catch (e) {}
        rows.push(backupCsvRow(["ref", "name", "email", "phone", "type", "status", "interest", "createdAt", "assignedTo", "source", "notes"]));
        (state.leads || []).forEach(l => rows.push(backupCsvRow([l.ref, l.name, l.email, l.phone, l.type, l.status, l.interest || "", l.createdAt, l.assignedTo || "", l.source || "", String(l.notes || "").slice(0, 200)])));
        backupDownload("esrealty-leads-" + exportedAt.slice(0, 10) + ".csv", rows.join("\n"), "text/csv");
        toast("Leads CSV downloaded");
      } else {
        const base = location.href.split("#")[0];
        rows.push(backupCsvRow(["id", "ref", "title", "status", "type", "dealType", "price", "city", "province", "barangay", "bedrooms", "bathrooms", "lotArea", "floorArea", "updatedAt", "url"]));
        (state.listings || []).forEach(l => rows.push(backupCsvRow([l.id, l.ref, l.title, l.status, l.type, l.dealType, l.price, l.city, l.province, l.barangay, l.bedrooms, l.bathrooms, l.lotArea, l.floorArea, l.updatedAt, base + "#/listing/" + encodeURIComponent(l.id)])));
        backupDownload("esrealty-listings-" + exportedAt.slice(0, 10) + ".csv", rows.join("\n"), "text/csv");
        toast("Listings CSV downloaded");
      }
    } catch (e) { toast("Export failed: " + esc(friendlyErr(e.message || e)), "err"); }
    finally { if (btn) { btn.disabled = false; btn.innerHTML = btn.dataset.label || "Export"; } }
  }
  let settingsHooked = false;
  function bindSettings() {
    refreshPushState().then(() => redrawPushCard());
    if (!settingsHooked) {
      settingsHooked = true;
      document.addEventListener("click", e => {
        const sv = e.target.closest("[data-settings-save]");
        if (sv) { settingsSaveForm(); return; }
        const cp = e.target.closest("[data-settings-pass]");
        if (cp) { settingsChangePassword(); return; }
        const bj = e.target.closest("[data-backup-json]");
        if (bj) { settingsBackupJson(bj); return; }
        const rs = e.target.closest("[data-restore-json]");
        if (rs) { const fi = document.getElementById("st-restore-file"); if (fi) fi.click(); return; }
        const bl = e.target.closest("[data-backup-leads-csv]");
        if (bl) { settingsBackupCsv("leads", bl); return; }
        const li = e.target.closest("[data-backup-listings-csv]");
        if (li) { settingsBackupCsv("listings", li); return; }
        const pOn = e.target.closest("[data-push-on]");
        if (pOn) { pushAction(pOn, pushTurnOn, "Phone alerts are on for this phone."); return; }
        const pOff = e.target.closest("[data-push-off]");
        if (pOff) { pushAction(pOff, pushTurnOff, "Phone alerts are off for this phone."); return; }
        const pKeys = e.target.closest("[data-push-keys]");
        if (pKeys) { pushMakeKeys(pKeys); return; }
        const pCopy = e.target.closest("[data-push-copy]");
        if (pCopy) { const el = document.getElementById("st-push-private"); if (el) { el.select(); try { navigator.clipboard.writeText(el.value).then(() => toast("Private key copied")); } catch (err) { document.execCommand("copy"); toast("Private key copied"); } } return; }
      });
      document.addEventListener("change", e => {
        const fi = e.target && e.target.closest ? e.target.closest("#st-restore-file") : null;
        if (fi) settingsRestoreFromFile(fi);
      });
    }
  }

  /* ================= LISTING INQUIRY + SHARE + STATS ================= */
  function lsStatBump(id, key) {
    if (!state.listingStats) state.listingStats = {};
    state.listingStats[id] = state.listingStats[id] || { views: 0, inquiries: 0 };
    state.listingStats[id][key] = (state.listingStats[id][key] || 0) + 1;
    save();
    bumpSharedListingStat(id, key);
  }
  function copyListingText(text, message) {
    const done = () => toast(message);
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done).catch(() => toast("Could not copy text", "err"));
      return;
    }
    const field = document.createElement("textarea");
    field.value = text;
    field.style.cssText = "position:fixed;left:-9999px";
    document.body.appendChild(field);
    field.select();
    const copied = document.execCommand("copy");
    field.remove();
    toast(copied ? message : "Could not copy text", copied ? "" : "err");
  }
